class Solution {
public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        root = new TrieNode();
        for (const string& w : words) insert(w);
        rows = board.size();
        cols = board[0].size();

        for (int i = 0; i < rows; ++i)
            for (int j = 0; j < cols; ++j)
                dfs(board, i, j, root);

        sort(result.begin(), result.end());          // ensure deterministic order
        return result;
    }

private:
    struct TrieNode {
        TrieNode* child[26];
        string word;               // non‑empty only at word end
        TrieNode() {
            fill(begin(child), end(child), nullptr);
        }
    };
    TrieNode* root = nullptr;
    vector<string> result;
    int rows = 0, cols = 0;

    void insert(const string& w) {
        TrieNode* node = root;
        for (char ch : w) {
            int idx = ch - 'a';
            if (!node->child[idx]) node->child[idx] = new TrieNode();
            node = node->child[idx];
        }
        node->word = w;
    }

    void dfs(vector<vector<char>>& board, int i, int j, TrieNode* node) {
        char c = board[i][j];
        if (c == '#') return;
        int idx = c - 'a';
        node = node->child[idx];
        if (!node) return;

        if (!node->word.empty()) {
            result.push_back(node->word);
            node->word.clear();               // avoid duplicates
        }

        board[i][j] = '#';                     // mark visited
        if (i > 0)     dfs(board, i - 1, j, node);
        if (i + 1 < rows) dfs(board, i + 1, j, node);
        if (j > 0)     dfs(board, i, j - 1, node);
        if (j + 1 < cols) dfs(board, i, j + 1, node);
        board[i][j] = c;                       // restore
    }
};
